def read_experiment_plan_with_status(project: str) -> str:
    """Read ``experiment_plan.yaml`` and overlay live status from the registry.

    The plan stores **planning intent only** (claim / priority / depends_on
    / description). Status is derived per call from ``registry_id``:

      - registry_id set + entry exists → registry status / conclusion / metrics
      - registry_id set + entry missing → status = "orphaned"
      - registry_id absent → status = "planned"

    Args:
        project: Project name.
    """
    from core.tools.experiment_plan import (
        read_experiment_plan_with_status as _read,
    )
    return _tool_result_to_str(_read(project))


