def compute_coverage_matrix(project: str) -> str:
    """Group plan entries by ``claim`` and report coverage per claim.

    Returns claim → {experiments, counts{planned/running/done/failed/orphaned},
    coverage, coverage_pct} plus a summary across all claims. Unassigned
    entries (no ``claim`` field) are listed separately so Director can spot
    plan gaps.

    Derived view — nothing is persisted. Recompute as often as needed.

    Args:
        project: Project name.
    """
    from core.tools.experiment_plan import (
        compute_coverage_matrix as _compute,
    )
    return _tool_result_to_str(_compute(project))


