def _load_registry_experiments(project: str) -> dict[str, dict]:
    """Read the registry once and return the {exp_id: entry} map.

    Imported lazily to avoid pulling registry dependencies into modules
    that only need plan reads (e.g. session prompts).
    """
    try:
        from core.tools.registry import get_registry_path
        reg_path = get_registry_path(project)
    except Exception:
        return {}
    if not reg_path.exists():
        return {}
    try:
        data = yaml.safe_load(reg_path.read_text(encoding="utf-8")) or {}
    except Exception:
        logger.warning("Failed to parse registry at %s", reg_path, exc_info=True)
        return {}
    experiments = data.get("experiments")
    if not isinstance(experiments, dict):
        return {}
    return experiments


def _attach_status(entry: dict, registry: dict[str, dict]) -> dict:
    """Return a copy of ``entry`` with status / conclusion / metrics from registry.

    Never mutates the input. The returned dict is what callers display —
    on-disk YAML stays untouched.
    """
    merged = dict(entry)
    reg_id = entry.get("registry_id")
    if reg_id:
        reg_exp = registry.get(reg_id)
        if reg_exp:
            merged["status"] = reg_exp.get("status", STATUS_ORPHANED)
            if "conclusion" in reg_exp:
                merged["conclusion"] = reg_exp.get("conclusion")
            if "metrics" in reg_exp:
                merged["metrics"] = reg_exp.get("metrics")
        else:
            merged["status"] = STATUS_ORPHANED
    else:
        merged["status"] = STATUS_PLANNED
    return merged


