def _coverage_bucket(status: str, conclusion: str | None = None) -> str:
    """Map a (status, conclusion) pair to a coverage bucket."""
    if status == STATUS_PLANNED:
        return "planned"
    if status == STATUS_ORPHANED:
        return "orphaned"
    if status == "DONE":
        if conclusion == "success":
            return "done"
        if conclusion in ("failed", "killed", "negative"):
            return "failed"
        return "done"  # unknown conclusion — count as done so it isn't pending
    # PREPARING / PENDING / QUEUED / ALLOCATED / RUNNING / ANALYZING / DEPLOY*
    return "running"


def _empty_bucket_counts() -> dict[str, int]:
    return {b: 0 for b in _COVERAGE_BUCKETS}


def compute_coverage_matrix(project: str) -> ToolResult:
    """Group plan entries by ``claim`` and report coverage per claim.

    Coverage = experiments whose ``status == DONE`` (regardless of
    conclusion), divided by total experiments in that claim. Claims with
    zero experiments report ``coverage_pct = 0.0``.

    Returns:
        ToolResult.data = {
            "claims": ["Claim 1", "Claim 2", ...],
            "matrix": {
                "Claim 1": {
                    "experiments": [{...}, {...}],
                    "counts": {"planned": 2, "running": 1, "done": 3, ...},
                    "total": 6,
                    "coverage": "3/6",
                    "coverage_pct": 50.0,
                },
                ...
            },
            "unassigned": [{...}],   # entries without a `claim` field
            "summary": {
                "total_experiments": N,
                "total_claims": M,
                "counts": {"planned": ..., "running": ..., "done": ...},
                "coverage": "K/N",
                "coverage_pct": ...,
            },
        }

    The ``unassigned`` list lets Director see which plan entries still
    need a claim attached — important for keeping the matrix honest.
    """
    plan_res = read_experiment_plan_with_status(project)
    if not plan_res.success:
        return plan_res

    entries: list[dict] = plan_res.data.get("experiments", []) or []

    by_claim: dict[str, list[dict]] = {}
    unassigned: list[dict] = []
    for e in entries:
        claim = e.get("claim")
        if claim:
            by_claim.setdefault(claim, []).append(e)
        else:
            unassigned.append(e)

    matrix: dict[str, dict] = {}
    overall_counts = _empty_bucket_counts()
